// i18n runtime for Emoji Munchers.
//
// The string table is no longer baked into this file. Every language --
// English included -- lives in public/locales/<lang>.json, fetched at
// runtime by initI18n(). That's the single source of truth; there is no
// second copy to keep in sync (the old i18n-source/en.json is gone).
//
// Locale files for every language except English are machine-generated by
// scripts/translate.mjs. Never hand-edit them -- see the "human overrides"
// note in the README: corrections go in <lang>.overrides.json, which the
// generator merges on top and never writes to.
//
// LANGUAGE CODES are lowercase-with-hyphens everywhere -- filenames, URL
// params, localStorage values, comparisons. normalizeLang() enforces that
// on the way in, because macOS is case-insensitive but the Vercel build
// environment is not: a file named pt-BR.json works locally and 404s in
// production. Anything arriving from a URL or storage gets normalized
// before it's used to build a filename.
//
// t(key, vars) looks up a string and fills in any {placeholder} tokens
// (e.g. t('round_progress', { round: 2, total: 3 })). Lookup falls back
// per-key to English, so a key missing from fr.json renders the English
// string rather than the raw key; only a key missing from English too
// shows up as the raw key, which is the visibly-broken-text signal a typo
// deserves.

// Interface languages are lowercase-hyphen. Two normalizations matter:
// underscores to hyphens (pt_BR -> pt-br), and the bare "pt" alias -- the
// QMoji 2.0 homescreen's picker only offers generic "pt", but the only
// Portuguese locale files that exist are pt-br and pt-pt, so bare "pt"
// resolves to Brazilian Portuguese rather than 404ing back to English.
// There is deliberately no pt.json; this alias is what makes the
// homescreen's existing Portuguese option work end to end.
function normalizeLang(code) {
  if (!code) return "";
  var lang = String(code).trim().toLowerCase().replace(/_/g, "-");
  if (lang === "pt") return "pt-br";
  return lang;
}

// Preferred interface language, by precedence: ?uiLang -> localStorage
// -> "en". Note this is what the player *asked* for, normalized, not
// necessarily what's available -- availability is decided by whether
// locales/<lang>.json actually loads (see initI18n), not by checking a
// baked-in table of known languages. Adding a language is therefore just
// adding a file.
//
// Read straight from the URL rather than waiting on arcade-client.js's
// async initArcade(), so the very first paint already uses the language
// this game was launched with instead of only catching up on a later
// visit once initArcade() has persisted it to localStorage.
function resolveI18nLang() {
  try {
    var fromUrl = normalizeLang(new URLSearchParams(location.search).get("uiLang"));
    if (fromUrl) return fromUrl;
    var fromStorage = normalizeLang(localStorage.getItem("qmoji.uiLang"));
    if (fromStorage) return fromStorage;
  } catch (e) {
    /* localStorage/URL access can throw in some embedded contexts -- fall through to "en" */
  }
  return "en";
}

// Populated by initI18n(). Until it resolves, every table is empty and
// t() would return raw keys -- which is exactly why nothing may render
// before the promise settles. See initI18n's contract below.
var I18N_STRINGS = {};
var I18N_ACTIVE_LANG = "en";

function loadLocale(lang) {
  return fetch("locales/" + encodeURIComponent(lang) + ".json").then(function (res) {
    if (!res.ok) throw new Error("locale " + lang + " -> HTTP " + res.status);
    return res.json();
  });
}

// Loads English (always, as the per-key fallback) plus the resolved
// language, then resolves. NEVER REJECTS: callers gate their first paint
// on this promise, so a rejection would mean a permanently blank page. A
// missing or malformed locale file degrades to English and logs; a
// missing English file degrades to raw keys, still rendering a usable
// (if ugly) UI rather than nothing.
function initI18n() {
  return loadLocale("en")
    .then(function (en) {
      I18N_STRINGS.en = en;
    })
    .catch(function (e) {
      I18N_STRINGS.en = {};
      console.error("i18n: could not load English strings --", e.message);
    })
    .then(function () {
      var want = resolveI18nLang();
      if (want === "en") return null;
      return loadLocale(want)
        .then(function (table) {
          I18N_STRINGS[want] = table;
          I18N_ACTIVE_LANG = want;
        })
        .catch(function (e) {
          // Not an error -- asking for a language nobody has translated
          // yet is a normal thing for a URL to do. English is the answer.
          I18N_ACTIVE_LANG = "en";
          console.info("i18n: falling back to English --", e.message);
        });
    });
}

function t(key, vars) {
  var table = I18N_STRINGS[I18N_ACTIVE_LANG] || I18N_STRINGS.en || {};
  var en = I18N_STRINGS.en || {};
  // Per-key fallback: a key the active language is missing renders the
  // English string, never the raw key.
  var text = table[key] || en[key] || key;
  if (vars) {
    Object.keys(vars).forEach(function (k) {
      text = text.split("{" + k + "}").join(vars[k]);
    });
  }
  return text;
}

// Applies every static (non-templated) string in one pass on load --
// anything with dynamic content (a score, a room code, a countdown) is set
// directly by client.js via t() instead, since data-i18n has no way to
// carry variables.
//
// Also drops the render-blocking class that index.html sets on <html>.
// The document is hidden until this point on purpose: with the string
// table arriving over the network, anything painted earlier would show
// raw snake_case keys for a frame. Revealing here -- after the static
// text is in the DOM, not merely after the fetch resolves -- is what
// makes that flash impossible. Safe to call more than once.
function applyStaticTranslations() {
  document.querySelectorAll("[data-i18n]").forEach(function (el) {
    el.textContent = t(el.getAttribute("data-i18n"));
  });
  document.querySelectorAll("[data-i18n-placeholder]").forEach(function (el) {
    el.setAttribute("placeholder", t(el.getAttribute("data-i18n-placeholder")));
  });
  document.documentElement.classList.remove("i18n-loading");
}
